                "type": "string"
              }
            },
            "required": [
              "source",
              "observation"
            ]
          },
          "description": "Evidence items supporting this update."
        }
      },
      "required": [
        "name"
      ]
    }
  }
}
{
  "type": "function",
  "function": {
    "name": "execute_code",
    "description": "Execute Python code",
    "parameters": {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "description": "Python code to execute"
        }
      },
      "required": [
        "code"
      ]
    }
  }
}
